package com.quizarena.server;
import com.quizarena.dao.ResultDao; import com.quizarena.model.*; import java.util.*; import java.util.concurrent.*;
final class Room {
 final String code,category,difficulty; final int count,seconds,max; final List<Question> questions; final Map<ClientHandler,Integer> scores=new ConcurrentHashMap<>(); final Map<ClientHandler,Integer> correct=new ConcurrentHashMap<>(); final Map<ClientHandler,Long> response=new ConcurrentHashMap<>(); final Map<ClientHandler,List<PlayerAnswer>> playerAnswers=new ConcurrentHashMap<>(); int index=-1; boolean started,finished;
 Room(String code,String category,String difficulty,int count,int seconds,int max,List<Question> questions){this.code=code;this.category=category;this.difficulty=difficulty;this.count=count;this.seconds=seconds;this.max=max;this.questions=questions;}
 synchronized void add(ClientHandler c){if(scores.size()>=max)throw new IllegalStateException("Room is full");scores.put(c,0);correct.put(c,0);response.put(c,0L);playerAnswers.put(c,Collections.synchronizedList(new ArrayList<>()));broadcast("PLAYER|"+c.user.username()+"|"+scores.size());}
 synchronized void start(){if(started)return;started=true;next();}
 synchronized void next(){if(finished)return;index++;if(index>=questions.size()){finished=true;persist();broadcast("FINISHED|"+leaderboard());return;}Question q=questions.get(index);broadcast("QUESTION|"+index+"|"+questions.size()+"|"+seconds+"|"+q.id()+"|"+escape(q.text())+"|"+escape(q.a())+"|"+escape(q.b())+"|"+escape(q.c())+"|"+escape(q.d()));QuizServer.SCHEDULER.schedule(this::next,seconds+1,TimeUnit.SECONDS);}
 synchronized void answer(ClientHandler c,long id,char selected,long elapsed){if(index<0||index>=questions.size()||id!=questions.get(index).id())return;String key=c+":"+index;if(c.answers.contains(key))return;c.answers.add(key);Question q=questions.get(index);boolean isCorrect=Character.toUpperCase(selected)==q.correctOption();if(isCorrect){scores.compute(c,(k,v)->v+100);correct.compute(c,(k,v)->v+1);}response.compute(c,(k,v)->v+elapsed);playerAnswers.get(c).add(new PlayerAnswer(q.id(),String.valueOf(Character.toUpperCase(selected)),isCorrect,elapsed));broadcast("LEADERBOARD|"+leaderboard());}
 String leaderboard(){List<String> rows=new ArrayList<>();scores.keySet().stream().sorted(Comparator.comparingInt((ClientHandler c)->scores.get(c)).reversed().thenComparingLong(response::get)).forEach(c->rows.add(c.user.username()+","+scores.get(c)+","+correct.get(c)));return String.join(";",rows);}
 void remove(ClientHandler c){scores.remove(c);correct.remove(c);response.remove(c);}
 private void persist(){List<ClientHandler> ordered=new ArrayList<>(scores.keySet());ordered.sort(Comparator.comparingInt((ClientHandler c)->scores.get(c)).reversed().thenComparingLong(response::get));List<PlayerScore> rows=new ArrayList<>();Map<Long,List<PlayerAnswer>> savedAnswers=new HashMap<>();int rank=1;for(ClientHandler c:ordered){List<PlayerAnswer> list=playerAnswers.get(c);Set<Long> answeredIds=new HashSet<>();for(PlayerAnswer a:list)answeredIds.add(a.questionId());for(Question q:questions)if(!answeredIds.contains(q.id()))list.add(new PlayerAnswer(q.id(),null,false,0));rows.add(new PlayerScore(c.user.id(),scores.get(c),correct.get(c),response.get(c),rank++));savedAnswers.put(c.user.id(),list);}try{long sessionId=new ResultDao().save(code,category,difficulty,questions.size(),rows,savedAnswers);for(ClientHandler c:ordered)c.send("ANALYSIS|"+String.join(";",new ResultDao().analysis(sessionId,c.user.id())));}catch(Exception e){System.err.println("Could not persist quiz result: "+e.getMessage());}}
 void broadcast(String line){scores.keySet().forEach(c->c.send(line));}
 static String escape(String s){return s.replace("|","/");}
}
